#include<bits/stdc++.h>
using namespace std;

int Packing(int k1,int k2,int k3,int k4,int k5,int k6)
{
    int n,x,y;
    int p2[4]={0,5,3,1};//p2[m]：一个箱子里放m个3×3之后，还能放多少个2×2
    n=(k3+3)/4+k4+k5+k6;
    /*
    6×6：
    - 1个6×6单独一箱：+k6
    - 1个5×5单独一箱，余下空间只能放1×1：+k5
    - 1个4×4单独一箱，余下最多放5个2×2：+k4
    - 一箱最多放4个3×3，向上取整 (k3+3)/4
    */
    x=5*k4+p2[k3%4];
    //现在所有已经开出来的箱子里，一共还能容纳x个2×2
    if(k2>x) n+=(k2-x+8)/9;
    // 2×2多出来的部分，每箱最多放9个2×2，向上取整
    y=36*n-36*k6-25*k5-16*k4-9*k3-4*k2;//按照格子数，6*6是36个格子……
    //所有已开箱子剩下的空位总数（用来放1×1）
    if(k1>y) n+=(k1-y+35)/36;
    // 1×1不够放，新增箱子，每箱36个1×1，向上取整
    return n;
}
